<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Maintenance', href: '/owner/maintenance' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';

    type Room = { id: number; code: string };
    type Property = { id: number; name: string; rooms: Room[] };
    type Job = { id: number; status: string; category: string; description: string; blocks_room: boolean; scheduled_start_date: string | null; scheduled_end_exclusive: string | null; room: Room | null; property: { id: number; name: string }; vendor_name: string | null };
    type PaginationLink = { url: string | null; label: string; active: boolean };
    let { jobs, properties, filters }: { jobs: { data: Job[]; links: PaginationLink[]; from: number | null; to: number | null; total: number }; properties: Property[]; filters: { property_id: string; status: string } } = $props();
    let blockRoom = $state(false);

    const labels: Record<string, string> = { reported: 'Dilaporkan', scheduled: 'Dijadwalkan', completed: 'Selesai', cancelled: 'Dibatalkan' };
</script>

<AppHead title="Maintenance" />
<main class="space-y-6 p-4 md:p-8">
    <header class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Perawatan</p><h1 class="text-3xl font-semibold tracking-tight">Maintenance</h1><p class="text-sm text-muted-foreground">Catat pekerjaan servis. Jadwal yang memblokir kamar tidak boleh bertabrakan dengan booking atau tenancy.</p></header>
    <section class="space-y-4 rounded-xl border bg-card p-5 shadow-sm"><div><h2 class="text-lg font-semibold">Laporkan pekerjaan</h2><p class="text-sm text-muted-foreground">Catatan biaya dan pembayaran maintenance dikelola terpisah.</p></div>
        <Form action="/owner/maintenance" method="post" class="space-y-4">{#snippet children({ errors, processing })}
            <div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><label for="property_id" class="text-sm font-medium">Properti <span aria-hidden="true">*</span></label><select id="property_id" name="property_id" required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Pilih properti</option>{#each properties as property (property.id)}<option value={property.id}>{property.name}</option>{/each}</select><InputError message={errors.property_id} /></div><div class="space-y-2"><label for="room_id" class="text-sm font-medium">Kamar terkait</label><select id="room_id" name="room_id" class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Fasilitas umum / tanpa kamar</option>{#each properties as property (property.id)}<optgroup label={property.name}>{#each property.rooms as room (room.id)}<option value={room.id}>{room.code}</option>{/each}</optgroup>{/each}</select><InputError message={errors.room_id} /></div></div>
            <div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><label for="category" class="text-sm font-medium">Kategori <span aria-hidden="true">*</span></label><select id="category" name="category" required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Pilih kategori</option><option value="ac">AC</option><option value="bathroom">Kamar mandi</option><option value="electrical">Listrik</option><option value="water">Air</option><option value="door">Pintu</option><option value="painting">Pengecatan</option><option value="common_facility">Fasilitas umum</option><option value="other">Lainnya</option></select><InputError message={errors.category} /></div><div class="space-y-2"><label for="vendor_name" class="text-sm font-medium">Teknisi/vendor</label><Input id="vendor_name" name="vendor_name" maxlength={160} /><InputError message={errors.vendor_name} /></div></div>
            <div class="space-y-2"><label for="description" class="text-sm font-medium">Deskripsi pekerjaan <span aria-hidden="true">*</span></label><textarea id="description" name="description" rows={3} required maxlength={2000} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.description} /></div>
            <label class="flex items-start gap-2 text-sm"><input type="checkbox" name="blocks_room" value="1" bind:checked={blockRoom} class="mt-0.5 size-4 rounded border" /><span>Jadwalkan sebagai pekerjaan yang membuat kamar tidak tersedia</span></label><InputError message={errors.blocks_room} />
            {#if blockRoom}<div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><label for="scheduled_start_date" class="text-sm font-medium">Mulai</label><Input id="scheduled_start_date" name="scheduled_start_date" type="date" required /><InputError message={errors.scheduled_start_date} /></div><div class="space-y-2"><label for="scheduled_end_exclusive" class="text-sm font-medium">Kamar tersedia kembali mulai</label><Input id="scheduled_end_exclusive" name="scheduled_end_exclusive" type="date" required /><p class="text-xs text-muted-foreground">Batas akhir tidak termasuk.</p><InputError message={errors.scheduled_end_exclusive} /></div></div>{/if}
            <InputError message={errors.maintenance} /><div class="flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Menyimpan…' : 'Simpan pekerjaan'}</Button></div>
        {/snippet}</Form>
    </section>
    <Form action="/owner/maintenance" method="get" class="grid gap-3 rounded-xl border bg-card p-4 sm:grid-cols-3 sm:items-end">{#snippet children({ processing })}<div class="space-y-1"><label for="filter_property_id" class="text-sm font-medium">Properti</label><select id="filter_property_id" name="property_id" value={filters.property_id} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Semua properti</option>{#each properties as property (property.id)}<option value={property.id}>{property.name}</option>{/each}</select></div><div class="space-y-1"><label for="filter_status" class="text-sm font-medium">Status</label><select id="filter_status" name="status" value={filters.status} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Semua status</option><option value="reported">Dilaporkan</option><option value="scheduled">Dijadwalkan</option><option value="completed">Selesai</option><option value="cancelled">Dibatalkan</option></select></div><Button type="submit" disabled={processing}>Terapkan filter</Button>{/snippet}</Form>
    <section class="overflow-hidden rounded-xl border bg-card shadow-sm" aria-label="Riwayat maintenance">
        {#if jobs.data.length === 0}<div class="p-10 text-center"><h2 class="font-medium">Belum ada pekerjaan</h2><p class="mt-1 text-sm text-muted-foreground">Kerusakan dan servis yang dilaporkan akan tersimpan di sini.</p></div>{:else}<div class="overflow-x-auto"><table class="w-full min-w-[48rem] text-left text-sm"><thead class="border-b bg-muted/40 text-muted-foreground"><tr><th class="px-5 py-3 font-medium">Pekerjaan</th><th class="px-5 py-3 font-medium">Properti / kamar</th><th class="px-5 py-3 font-medium">Jadwal</th><th class="px-5 py-3 font-medium">Status</th><th class="px-5 py-3 text-right font-medium">Aksi</th></tr></thead><tbody class="divide-y">{#each jobs.data as job (job.id)}<tr><td class="px-5 py-4"><p class="font-medium">{job.category}</p><p class="mt-1 max-w-sm truncate text-xs text-muted-foreground">{job.description}</p></td><td class="px-5 py-4"><p>{job.property.name}</p><p class="text-xs text-muted-foreground">{job.room ? `Kamar ${job.room.code}` : 'Fasilitas umum'}{job.blocks_room ? ' · memblokir kamar' : ''}</p></td><td class="px-5 py-4">{job.scheduled_start_date && job.scheduled_end_exclusive ? `${job.scheduled_start_date} – ${job.scheduled_end_exclusive}` : 'Belum dijadwalkan'}</td><td class="px-5 py-4"><span class="rounded-full border px-2.5 py-1 text-xs">{labels[job.status] ?? job.status}</span></td><td class="px-5 py-4 text-right"><Link href={`/owner/maintenance/${job.id}`} class="text-primary underline-offset-4 hover:underline">Detail</Link></td></tr>{/each}</tbody></table></div><footer class="flex flex-wrap items-center justify-between gap-4 border-t px-5 py-4 text-sm"><p class="text-muted-foreground">Menampilkan {jobs.from ?? 0}–{jobs.to ?? 0} dari {jobs.total} pekerjaan</p><nav aria-label="Navigasi halaman" class="flex flex-wrap gap-1">{#each jobs.links as link, index (index)}{#if link.url}<Link href={link.url} class={`rounded border px-3 py-1.5 ${link.active ? 'bg-primary text-primary-foreground' : 'hover:bg-muted'}`}>{link.label}</Link>{:else}<span class="rounded border px-3 py-1.5 text-muted-foreground">{link.label}</span>{/if}{/each}</nav></footer>{/if}
    </section>
</main>
